*{box-sizing:border-box} :root{--ink:#272235;--muted:#948da1;--purple:#7657d8;--lilac:#eee8ff;--pink:#ff8ca8;--surface:#fff;--line:#f0edf5} body{margin:0;min-height:100vh;background:#f8f6fb;color:var(--ink);font-family:'DM Sans',sans-serif;overflow-x:hidden}.stage{min-height:100vh;max-width:1220px;margin:auto;padding:36px 36px;display:grid;grid-template-columns:1fr 390px 1fr;align-items:center;gap:40px}.intro{position:relative;padding-left:44px;align-self:center;z-index:1}.brand-mark{width:44px;height:44px;border-radius:15px;background:#28213a;color:white;font:800 24px Manrope;display:grid;place-items:center;position:relative;box-shadow:0 10px 24px #42345a25}.brand-mark span{position:absolute;font-size:12px;color:#ff9db3;right:4px;top:3px}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:800;color:#9b8cb9;margin:40px 0 14px}.intro h1{font:800 clamp(42px,5vw,62px)/1.07 Manrope,sans-serif;letter-spacing:-3.7px;margin:0;color:#282236}.intro h1 span{color:#8e72df}.intro-copy{font-size:15px;line-height:1.75;color:#8d8798;margin-top:22px}.intro-foot{display:flex;align-items:center;gap:9px;color:#8e8799;font-size:12px;margin-top:56px}.pulse-dot{width:8px;height:8px;background:#74c6a0;border-radius:50%;box-shadow:0 0 0 4px #74c6a01e}.orbit{position:absolute;border:1px solid #e8e2f1;border-radius:50%;z-index:-1;pointer-events:none}.orbit-one{width:210px;height:210px;right:-4px;top:56px}.orbit-two{width:130px;height:130px;right:36px;top:96px;border-color:#f0eafa}.phone-shell{width:352px;justify-self:center;position:relative;z-index:2}.phone-frame{position:relative;background:#211e27;border-radius:48px;padding:9px;box-shadow:0 35px 75px #33244925,0 8px 18px #241d3325,inset 0 0 0 1px #605b66}.phone-screen{height:min(740px,calc(100vh - 54px));min-height:620px;border-radius:40px;overflow:hidden;background:#f9f8fc;position:relative;display:flex;flex-direction:column}.status-bar{height:36px;flex-shrink:0;display:grid;grid-template-columns:1fr 72px 1fr;align-items:center;padding:0 22px;font-size:11px;font-weight:700;position:relative;z-index:5}.island{background:#17151a;width:67px;height:20px;border-radius:20px;justify-self:center}.status-icons{text-align:right;font-size:10px;letter-spacing:1px}.screen-content{flex:1;overflow-y:auto;scrollbar-width:none;padding-bottom:8px}.screen-content::-webkit-scrollbar{display:none}.phone-nav{height:58px;flex-shrink:0;margin:0 17px 7px;border-radius:20px;background:#fff;box-shadow:0 6px 25px #34214c0c;display:flex;justify-content:space-around;align-items:center;z-index:4}.nav-button{border:0;background:transparent;color:#aaa3b1;width:52px;height:45px;border-radius:15px;font-size:24px;cursor:pointer;transition:.2s}.nav-button.active{background:#f0ebff;color:#7657d8}.nav-button span{display:inline-block;transform:translateY(-1px)}.home-indicator{position:absolute;bottom:5px;width:98px;height:4px;border-radius:10px;background:#27232b;align-self:center;z-index:5}.phone-shadow{height:34px;width:260px;position:absolute;bottom:-29px;left:46px;background:#34254814;filter:blur(19px);border-radius:50%;z-index:-1}.hint-card{justify-self:center;align-self:end;margin-bottom:85px;width:218px;background:#fff;border:1px solid #f0edf5;border-radius:18px;padding:16px;box-shadow:0 15px 40px #3121440b;position:relative}.hint-icon{display:inline-grid;place-items:center;width:27px;height:27px;border-radius:9px;background:#f2edff;color:#8569df;margin-bottom:10px}.hint-card strong{font-size:13px}.hint-card p{color:#918a9c;font-size:11px;line-height:1.6;margin:4px 0 0}.hint-arrow{position:absolute;right:16px;top:19px;color:#b1a6c8;font-size:17px}
/* home */
.home-page{padding:9px 20px 16px}.greeting{display:flex;justify-content:space-between;align-items:center;margin:10px 0 18px}.greeting .small-date{font-size:11px;color:#97909f;margin-bottom:4px}.greeting h2{font:800 22px Manrope;margin:0;letter-spacing:-.7px}.avatar{width:39px;height:39px;border-radius:15px;background:#ffe5ec;display:grid;place-items:center;font-size:20px}.weather-card{border-radius:21px;padding:17px 17px 15px;background:linear-gradient(120deg,#8064d7,#9a80e5);color:white;position:relative;overflow:hidden;min-height:123px;box-shadow:0 10px 22px #8064d72a}.weather-card:after{content:'☀';position:absolute;right:17px;top:14px;font-size:61px;color:#ffffffa8}.weather-card .weather-label{font-size:11px;opacity:.8}.weather-card .weather-temp{font:800 32px Manrope;margin-top:7px}.weather-card .weather-desc{font-size:11px;opacity:.85;margin-top:1px}.weather-card .weather-city{position:absolute;bottom:15px;right:17px;font-size:10px;opacity:.8}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:21px 1px 12px}.section-heading h3{margin:0;font:800 14px Manrope}.section-heading button{border:0;background:transparent;color:#9c8acb;font-size:11px;cursor:pointer}.app-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px 8px}.app-tile{border:0;background:transparent;padding:0;color:var(--ink);font:inherit;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;min-width:0}.app-icon{height:51px;width:51px;border-radius:17px;display:grid;place-items:center;font-size:24px;box-shadow:0 5px 12px #2c20420d;transition:transform .18s,box-shadow .18s}.app-tile:hover .app-icon{transform:translateY(-3px);box-shadow:0 9px 15px #2c20421c}.app-label{font-size:10px;font-weight:600;white-space:nowrap}.icon-google{background:#fff;color:#4285f4}.icon-notes{background:#fff0c9;color:#cc9b27}.icon-weather{background:#e8e3ff;color:#7762d1}.icon-calc{background:#e3f7ed;color:#46a77e}.icon-gallery{background:#ffe5e9;color:#dc718a}.icon-messages{background:#def6ea;color:#39a879}.icon-clock{background:#e4edff;color:#5e81c6}.icon-music{background:#fbe4f3;color:#ca5fa1}.widget-title{display:flex;align-items:center;justify-content:space-between;margin-top:19px;font:800 13px Manrope}.widget-title span{font:500 10px 'DM Sans';color:#aaa2b2}.todo-card{background:white;border:1px solid #f2eff6;border-radius:17px;padding:13px 14px;margin-top:10px;display:flex;align-items:center;gap:11px}.todo-mark{height:34px;width:34px;border-radius:12px;background:#fff0e7;display:grid;place-items:center;color:#e29269}.todo-card strong{display:block;font-size:11px}.todo-card small{display:block;color:#a49baa;font-size:9px;margin-top:3px}.todo-count{margin-left:auto;background:#f5f1fc;border-radius:10px;padding:6px 8px;color:#856dd0;font-size:10px;font-weight:700}.dock{display:flex;justify-content:space-around;padding:12px 9px;background:#fff;border-radius:19px;margin-top:17px}.dock .app-icon{width:45px;height:45px;border-radius:15px}.dock .app-label{display:none}
/* app pages */
.app-page{height:100%;padding:5px 19px 16px;display:flex;flex-direction:column}.app-header{display:flex;align-items:center;gap:12px;margin:6px 0 18px;flex-shrink:0}.back-button{border:0;background:#fff;width:33px;height:33px;border-radius:12px;color:#756b83;font-size:21px;cursor:pointer;box-shadow:0 3px 12px #32204209}.app-header h2{font:800 19px Manrope;margin:0;letter-spacing:-.5px}.app-header .subhead{font-size:10px;color:#9a92a1;margin-top:3px}.google-page{background:linear-gradient(180deg,#f9f8fc,#f7f5fb)}.google-logo{font:800 27px Manrope;letter-spacing:-2px;text-align:center;margin:27px 0 23px}.google-logo .g-blue{color:#4285f4}.google-logo .g-red{color:#ea4335}.google-logo .g-yellow{color:#fbbc05}.google-logo .g-green{color:#34a853}.search-box{height:48px;display:flex;align-items:center;background:white;border:1px solid #eeeaf3;border-radius:16px;padding:0 13px;gap:9px;box-shadow:0 5px 16px #2d24400b}.search-box .glass{font-size:18px;color:#9891a0}.search-box input{border:0;outline:0;background:transparent;min-width:0;flex:1;font:500 12px 'DM Sans';color:#302a39}.search-box input::placeholder{color:#b4aebb}.search-box button{border:0;background:#f0ebff;color:#785bda;border-radius:10px;width:30px;height:30px;font-size:16px;cursor:pointer}.ai-tag{display:flex;align-items:center;gap:7px;color:#8d79c9;font-size:10px;margin:13px 5px 0}.ai-spark{font-size:13px}.quick-prompts{margin-top:24px}.quick-prompts h3{font-size:11px;color:#98909f;font-weight:600;margin:0 0 9px 2px}.prompt-chip{width:100%;display:flex;align-items:center;gap:11px;text-align:left;border:1px solid #eeeaf3;background:white;border-radius:13px;padding:11px 12px;margin-bottom:8px;color:#625b6a;font:500 11px 'DM Sans';cursor:pointer}.prompt-chip:hover{border-color:#d8cdf9;background:#fcfbff}.prompt-chip span:first-child{font-size:15px;color:#9076db}.response-wrap{margin-top:20px;display:none}.response-wrap.visible{display:block;animation:fadeUp .3s ease}.response-head{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700;margin-bottom:10px}.ai-avatar{width:24px;height:24px;display:grid;place-items:center;background:#eee8ff;color:#7e61d3;border-radius:9px}.response-card{background:#fff;border:1px solid #efebf5;border-radius:16px;padding:14px;font-size:11px;color:#625a6c;line-height:1.7;white-space:pre-wrap}.response-actions{display:flex;gap:8px;margin-top:10px}.mini-action{border:1px solid #eeeaf3;border-radius:9px;background:white;padding:7px 10px;color:#8d829c;font-size:10px;cursor:pointer}.search-bottom{margin-top:auto;color:#b1aab8;font-size:9px;text-align:center;padding:12px 0 2px}.typing{display:flex;gap:4px;padding:5px}.typing i{width:5px;height:5px;background:#a892e8;border-radius:50%;animation:bounce .6s infinite alternate}.typing i:nth-child(2){animation-delay:.15s}.typing i:nth-child(3){animation-delay:.3s}
/* notes */
.notes-page{background:#fffcf4}.notes-page .app-header h2{color:#2e2a35}.note-new{width:100%;height:43px;border:1px dashed #e6d9ac;border-radius:14px;background:#fffdf7;color:#9d8650;font:600 11px 'DM Sans';cursor:pointer;margin-bottom:13px}.notes-search{width:100%;height:38px;border:0;border-radius:12px;padding:0 12px;background:#f5f1e7;font:11px 'DM Sans';outline:none;margin-bottom:13px}.notes-list{display:flex;flex-direction:column;gap:9px;overflow:auto}.note-card{background:white;border:1px solid #f1ecde;border-radius:15px;padding:13px;cursor:pointer;text-align:left;color:#39343d;position:relative}.note-card strong{font-size:12px;display:block;padding-right:25px}.note-card p{font-size:10px;line-height:1.5;color:#908991;margin:6px 0 8px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.note-card time{font-size:9px;color:#b0a7a5}.note-delete{position:absolute;right:10px;top:9px;border:0;background:#fff3ef;color:#cb8b79;width:24px;height:24px;border-radius:8px;cursor:pointer}.note-editor{position:absolute;inset:43px 0 0;background:#fffcf4;z-index:3;padding:10px 19px 20px;display:none;flex-direction:column}.note-editor.open{display:flex}.editor-actions{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.editor-actions button{border:0;background:transparent;color:#98834d;font:600 11px 'DM Sans';cursor:pointer}.note-title-input,.note-body-input{border:0;outline:none;background:transparent;font-family:'DM Sans';color:#39343d;resize:none}.note-title-input{font:800 21px Manrope;margin:4px 0 12px}.note-body-input{font-size:13px;line-height:1.7;flex:1}.empty-state{text-align:center;color:#9f98a2;font-size:11px;padding:40px 15px;line-height:1.8}.empty-state span{display:block;font-size:28px;margin-bottom:8px}
/* utility apps */
.utility-card{background:white;border:1px solid #eeeaf3;border-radius:17px;padding:15px;margin-bottom:12px}.weather-big{text-align:center;padding:20px 12px;background:linear-gradient(140deg,#8063d4,#a187e7);color:white;border-radius:20px;margin-top:5px}.weather-big .sun{font-size:50px}.weather-big .temp{font:800 43px Manrope;margin:3px}.weather-big .condition{font-size:12px;opacity:.85}.weather-big input{margin-top:14px;width:100%;height:38px;border:0;border-radius:12px;background:#ffffff25;color:#fff;padding:0 12px;outline:none;font:11px 'DM Sans'}.weather-big input::placeholder{color:#ffffffad}.weather-facts{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:11px}.fact{background:white;border-radius:14px;padding:12px;font-size:10px;color:#98909f}.fact strong{display:block;color:#413a4c;font-size:13px;margin-top:5px}.calc-display{background:#282333;color:white;border-radius:20px;padding:20px;text-align:right;font:500 34px Manrope;min-height:88px;overflow:hidden}.calc-expression{font-size:11px;color:#aaa2b8;min-height:17px;margin-bottom:8px}.calc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:12px}.calc-key{border:0;border-radius:14px;height:54px;background:#fff;color:#46404f;font:600 16px Manrope;cursor:pointer}.calc-key.operator{background:#f0ebff;color:#8266d2}.calc-key.equals{background:#8063d4;color:white}.calc-key.clear{background:#fff0f2;color:#d47d93}.gallery-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.photo-tile{height:119px;border-radius:16px;border:0;cursor:pointer;color:#fff;font-size:36px;display:grid;place-items:center;position:relative;overflow:hidden}.photo-tile span{position:absolute;left:10px;bottom:9px;font-size:9px;font-weight:700;text-shadow:0 1px 5px #0005}.photo-tile:nth-child(1){background:linear-gradient(145deg,#ffd197,#f08e8f)}.photo-tile:nth-child(2){background:linear-gradient(145deg,#b5d9f9,#827bcf)}.photo-tile:nth-child(3){background:linear-gradient(145deg,#bbebcf,#5ba993)}.photo-tile:nth-child(4){background:linear-gradient(145deg,#f6c6df,#b37da8)}.chat-list{display:flex;flex-direction:column;gap:8px}.chat-row{width:100%;border:0;background:white;border-radius:15px;padding:12px;display:flex;align-items:center;gap:10px;text-align:left;cursor:pointer}.chat-face{height:38px;width:38px;border-radius:14px;background:#f2eaff;display:grid;place-items:center;font-size:19px}.chat-text{min-width:0;flex:1}.chat-text strong{display:block;font-size:11px}.chat-text span{display:block;color:#a099a6;font-size:9px;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chat-time{align-self:flex-start;color:#aaa1ae;font-size:8px}.chat-thread{display:flex;flex-direction:column;flex:1;min-height:0}.chat-messages{flex:1;overflow:auto;display:flex;flex-direction:column;gap:8px;padding:5px 1px}.bubble{max-width:80%;background:white;border-radius:14px 14px 14px 4px;padding:10px;font-size:10px;line-height:1.5;color:#57505e}.bubble.mine{align-self:flex-end;background:#eae3ff;border-radius:14px 14px 4px 14px}.chat-compose{display:flex;gap:7px;margin-top:9px}.chat-compose input{flex:1;min-width:0;border:0;background:white;border-radius:13px;padding:0 12px;height:39px;outline:none;font:10px 'DM Sans'}.chat-compose button{width:39px;border:0;border-radius:13px;background:#8063d4;color:white;font-size:17px;cursor:pointer}.clock-face{height:210px;width:210px;border-radius:50%;margin:12px auto 18px;background:radial-gradient(circle,#fff 58%,#eee9f8 59%,#fff 65%);border:4px solid #fff;box-shadow:0 8px 24px #33214412;position:relative}.clock-face:before{content:'';position:absolute;left:50%;top:50%;height:67px;width:3px;background:#665398;border-radius:4px;transform-origin:top;transform:rotate(0deg)}.clock-face:after{content:'';position:absolute;left:50%;top:50%;height:82px;width:2px;background:#d67e9b;border-radius:4px;transform-origin:top;transform:rotate(120deg)}.clock-center{position:absolute;width:9px;height:9px;border-radius:50%;background:#8063d4;left:calc(50% - 4px);top:calc(50% - 4px)}.clock-digital{text-align:center;font:700 29px Manrope}.clock-date{text-align:center;font-size:11px;color:#9c94a3;margin:5px}.music-card{background:linear-gradient(145deg,#d47bab,#8d64c8);border-radius:20px;color:white;text-align:center;padding:25px 15px}.album-art{width:140px;height:140px;margin:0 auto 18px;border-radius:28px;background:linear-gradient(145deg,#ffcfdd,#8971d6);display:grid;place-items:center;font-size:54px;box-shadow:0 10px 25px #3a245533}.music-card h3{font:800 16px Manrope;margin:0}.music-card p{font-size:11px;opacity:.78}.music-controls{display:flex;justify-content:center;align-items:center;gap:25px;margin-top:17px}.music-controls button{border:0;background:transparent;color:white;font-size:22px;cursor:pointer}.music-controls .play{height:48px;width:48px;border-radius:50%;background:white;color:#9063ba;font-size:18px}
.toast{position:absolute;bottom:72px;left:50%;transform:translate(-50%,10px);background:#292433;color:white;border-radius:12px;padding:10px 14px;font-size:10px;opacity:0;pointer-events:none;transition:.22s;white-space:nowrap;z-index:9}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes fadeUp{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}@keyframes bounce{to{transform:translateY(-4px);opacity:.5}}
@media(max-width:850px){.stage{grid-template-columns:1fr 352px;justify-content:center;padding:24px;gap:22px}.intro{padding-left:12px}.intro h1{font-size:45px}.hint-card{display:none}.orbit-one{right:-70px}.orbit-two{right:-31px}}@media(max-width:600px){body{background:#f9f8fc}.stage{display:block;padding:0;min-height:100dvh}.intro,.hint-card,.phone-shadow{display:none}.phone-shell{width:100%;height:100dvh;margin:0}.phone-frame{height:100%;padding:0;border-radius:0;background:#f9f8fc;box-shadow:none}.phone-screen{height:100%;min-height:0;border-radius:0}.status-bar{padding-top:2px}.phone-nav{margin-bottom:10px}.home-indicator{bottom:7px}.app-page{padding-left:21px;padding-right:21px}.app-editor{inset-top:44px}}

const $ = (s, root=document) => root.querySelector(s);
const screen = $('#screenContent');
const toastNode = $('#toast');
let toastTimer;
let activePage = 'home';
let noteDraftId = null;
let calcValue = '0', calcPrevious = '', calcOperator = null, calcFresh = false;
let selectedChat = null;
let musicPlaying = false;
const appMeta = {
  google:['Google','icon-google','G'], notes:['Note','icon-notes','▤'], weather:['Meteo','icon-weather','☀'], calculator:['Calcolatrice','icon-calc','＋'], gallery:['Foto','icon-gallery','▧'], messages:['Messaggi','icon-messages','●'], clock:['Orologio','icon-clock','◷'], music:['Musica','icon-music','♫']
};
const nowTime = () => new Date().toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});
function updateTime(){ $('#statusTime').textContent=nowTime(); }
updateTime(); setInterval(updateTime,30000);
function toast(msg){toastNode.textContent=msg;toastNode.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastNode.classList.remove('show'),2100)}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function getNotes(){try{return JSON.parse(localStorage.getItem('miniverse-notes')||'[]')}catch{return []}}
function saveNotes(items){localStorage.setItem('miniverse-notes',JSON.stringify(items))}
function renderHome(){activePage='home';setNav('home');let date=new Date().toLocaleDateString('it-IT',{weekday:'long',day:'numeric',month:'long'});date=date.charAt(0).toUpperCase()+date.slice(1);
screen.innerHTML=`<div class="home-page"><div class="greeting"><div><div class="small-date">${date}</div><h2>Ciao, Alex <span>✦</span></h2></div><div class="avatar">🌷</div></div><button class="weather-card" data-open="weather" style="width:100%;text-align:left;border:0;color:white;cursor:pointer"><div class="weather-label">IL METEO DI OGGI</div><div class="weather-temp">22°</div><div class="weather-desc">Soleggiato · perfetto per uscire</div><div class="weather-city">Milano　⌄</div></button><div class="section-heading"><h3>Le tue app</h3><button data-action="all-apps">Tutte le app　↗</button></div><div class="app-grid">${['google','notes','weather','calculator','gallery','messages','clock','music'].map(appTile).join('')}</div><div class="widget-title">La tua giornata <span>OGGI</span></div><div class="todo-card"><div class="todo-mark">✎</div><div><strong>Un'idea al volo?</strong><small>Salvala nelle tue Note</small></div><span class="todo-count">${getNotes().length} note</span></div><div class="dock">${['google','notes','messages','music'].map(appTile).join('')}</div></div>`;}
function appTile(id){let [name,style,icon]=appMeta[id];return `<button class="app-tile" data-open="${id}" aria-label="Apri ${name}"><span class="app-icon ${style}">${icon}</span><span class="app-label">${name}</span></button>`}
function setNav(key){document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.page===key))}
function go(page){switch(page){case'home':renderHome();break;case'search':renderGoogle();break;case'notes':renderNotes();break;default:renderApp(page)}}
function header(title,sub=''){return `<div class="app-header"><button class="back-button" data-action="back" aria-label="Indietro">‹</button><div><h2>${title}</h2>${sub?`<div class="subhead">${sub}</div>`:''}</div></div>`}
function renderGoogle(query=''){activePage='google';setNav('search');screen.innerHTML=`<div class="app-page google-page">${header('Google','La curiosità è il tuo superpotere')}<div class="google-logo"><span class="g-blue">G</span><span class="g-red">o</span><span class="g-yellow">o</span><span class="g-blue">g</span><span class="g-green">l</span><span class="g-red">e</span></div><form class="search-box" id="searchForm"><span class="glass">⌕</span><input id="searchInput" autocomplete="off" placeholder="Chiedi quello che vuoi…" value="${escapeHTML(query)}" aria-label="Cerca con Google"><button aria-label="Cerca">➜</button></form><div class="ai-tag"><span class="ai-spark">✦</span> Risposte create con l'AI di Miniverse</div><div class="quick-prompts"><h3>DA DOVE VUOI INIZIARE?</h3><button class="prompt-chip" data-query="Perché il cielo è blu?"><span>✧</span><span>Perché il cielo è blu?</span></button><button class="prompt-chip" data-query="Dammi un'idea per una merenda sana"><span>♡</span><span>Un'idea per una merenda sana</span></button><button class="prompt-chip" data-query="Come posso organizzare meglio la giornata?"><span>◷</span><span>Come organizzare la giornata?</span></button></div><div class="response-wrap" id="responseWrap"></div><div class="search-bottom">Una risposta AI per ogni tua domanda · ✦</div></div>`;if(query)askAI(query)}
function buildAnswer(q){let s=q.toLowerCase();let answer='', tip='';
if(/\b(chi|who)\b/.test(s)||/chi è|chi era/.test(s)){answer=`Per rispondere a “${q}”, mi serve capire a quale persona ti riferisci. Aggiungi un dettaglio, per esempio il suo ambito o il periodo storico, e posso darti una risposta più precisa.`;tip='Prova: “Chi era Marie Curie?”'}
else if(/\b(quanto|quanti|quante|calcola|calcolare|somma|moltiplica)\b/.test(s)||/[0-9]+\s*[+*/-]\s*[0-9]+/.test(s)){let nums=s.match(/-?\d+(?:[.,]\d+)?/g)?.map(x=>Number(x.replace(',','.')))||[];let math=s.match(/(-?\d+(?:[.,]\d+)?)\s*([+*/×÷-])\s*(-?\d+(?:[.,]\d+)?)/);if(math){let a=Number(math[1].replace(',','.')),b=Number(math[3].replace(',','.')),op=math[2];let result=op==='+'?a+b:op==='-'?a-b:(op==='*'||op==='×')?a*b:b!==0?a/b:'non definito';answer=`${a} ${op} ${b} = ${result}.\n\nHo individuato l'operazione nella tua domanda e l'ho risolta. Se vuoi, puoi chiedermi anche di spiegare i passaggi.`}else if(nums.length){answer=`Nella tua domanda ho trovato questi numeri: ${nums.join(', ')}. Per fare un calcolo preciso, scrivimi l'operazione completa, ad esempio “quanto fa 18 × 7?”.`}else answer='Certo! Scrivimi l’operazione che vuoi risolvere, per esempio “quanto fa 125 diviso 5?”';tip='Puoi chiedermi un calcolo o una conversione'}
else if(/meteo|tempo|temperatur|piove/.test(s)){answer='Per il meteo aggiornato apri l’app Meteo del telefono. Posso però aiutarti a interpretare le previsioni: controlla temperatura, probabilità di pioggia e vento prima di uscire, così scegli cosa indossare.';tip='Apri l’app Meteo per la tua giornata'}
else if(/ricetta|cucin|mangiare|merenda|pranzo|cena/.test(s)){answer='Un’idea semplice e gustosa: prepara una bowl con una base di riso o cous cous, verdure di stagione e una fonte proteica come ceci o uova. Aggiungi olio, limone e le tue erbe preferite.\n\nPer personalizzarla, dimmi cosa hai in frigo o se hai preferenze alimentari.';tip='Posso adattare l’idea a quello che hai in casa'}
else if(/spiega|cos'è|cosa è|come funziona|perché|perche/.test(s)){let topic=q.replace(/^(spiegami|spiega|cos'è|cosa è|come funziona|perché|perche)\s*/i,'').replace(/[?!.]+$/,'');answer=`In breve: ${topic||q} è un argomento che si può capire partendo dalle sue idee fondamentali e collegandole a esempi concreti.\n\nPer orientarti, pensa a cosa lo causa, come funziona e quali effetti produce. Questo schema aiuta a trasformare una domanda grande in passaggi più semplici.\n\nSe vuoi, chiedimi “spiegamelo come se avessi 10 anni” oppure aggiungi un contesto e approfondisco.`;tip='Risposta AI dimostrativa: chiedi un esempio per approfondire'}
else if(/idea|consigli|consiglio|sugger/.test(s)){answer=`Ecco un punto di partenza per “${q}”: scegli un obiettivo piccolo e concreto, poi trasformalo in un primo passo che puoi fare in meno di 10 minuti.\n\nPer trovare un’idea più adatta a te, considera cosa ti piace, il tempo che hai e le risorse a disposizione. Raccontami uno di questi dettagli e ti propongo qualcosa di più mirato.`;tip='Piccoli passi, grandi idee ✨'}
else if(/traduc|inglese|francese|spagnolo|significa/.test(s)){answer=`Posso aiutarti con la lingua! Per tradurre con precisione, incolla la frase e dimmi verso quale lingua. Se invece vuoi il significato di una parola, scrivila insieme alla frase in cui l'hai trovata.`;tip='Aggiungi la frase completa per più contesto'}
else{answer=`Bella domanda: “${q}”.\n\nPer affrontarla, parto dal punto centrale e distinguo ciò che sappiamo da ciò che dipende dal contesto. Una buona risposta può cambiare in base ai tuoi obiettivi e alle informazioni disponibili.\n\nDimmi cosa ti interessa di più — una spiegazione semplice, un esempio pratico o una lista di idee — e ti rispondo in modo più mirato.`;tip='Puoi fare una domanda di approfondimento'}
return {answer,tip}}
function askAI(text){const q=text.trim();if(!q)return;let wrap=$('#responseWrap');wrap.classList.add('visible');wrap.innerHTML=`<div class="response-head"><span class="ai-avatar">✦</span> Miniverse AI <span style="color:#aaa;font-weight:400">sta pensando…</span></div><div class="response-card"><div class="typing"><i></i><i></i><i></i></div></div>`;setTimeout(()=>{if(!$('#responseWrap'))return;let {answer,tip}=buildAnswer(q);wrap.innerHTML=`<div class="response-head"><span class="ai-avatar">✦</span> Miniverse AI <span style="color:#aaa;font-weight:400">· adesso</span></div><div class="response-card">${escapeHTML(answer)}<div style="font-size:9px;color:#a49aaa;margin-top:12px">${escapeHTML(tip)}</div></div><div class="response-actions"><button class="mini-action" data-action="copy-answer">▢　Copia</button><button class="mini-action" data-action="save-answer">＋　Salva nelle Note</button></div>`;wrap.dataset.answer=answer;wrap.dataset.question=q;},650)}
