function calculatorPress(key){const disp=$('#calcDisplay'),expr=$('#calcExpression');if(!disp)return;if(key==='AC'){calcValue='0';calcPrevious='';calcOperator=null;calcFresh=false;expr.textContent=''}else if(key==='⌫'){calcValue=calcValue.length>1?calcValue.slice(0,-1):'0'}else if(key==='±'){calcValue=String(Number(calcValue)*-1)}else if(key==='%'){calcValue=String(Number(calcValue)/100)}else if(['+','−','×','÷'].includes(key)){calcPrevious=calcValue;calcOperator=key;calcFresh=true;expr.textContent=`${calcPrevious} ${key}`}else if(key==='='){if(calcOperator){let a=Number(calcPrevious),b=Number(calcValue),r=calcOperator==='+'?a+b:calcOperator==='−'?a-b:calcOperator==='×'?a*b:b===0?'Errore':a/b;expr.textContent=`${calcPrevious} ${calcOperator} ${calcValue} =`;calcValue=String(r);calcOperator=null;calcFresh=true}}else if(key==='.') {if(calcFresh){calcValue='0.';calcFresh=false}else if(!calcValue.includes('.'))calcValue+='.'}else{if(calcFresh){calcValue=key;calcFresh=false}else calcValue=calcValue==='0'?key:calcValue+key}disp.textContent=calcValue.length>12?Number(calcValue).toPrecision(8):calcValue}
